import {roundResult,tieReason} from './result-model.js';
import {roomBets} from './bets.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderRoundResult(panel,room,{error='',force=false}={}){
 const data=roundResult(room),signature=JSON.stringify([room.id,room.round,room.hostId,data]);
 if(panel.dataset.result===signature&&!error&&!force)return;
 panel.dataset.result=signature;panel.dataset.hasLast=String(!!data.last);const bet=roomBets[data.bet]||roomBets.none,winners=data.winners.map(r=>esc(r.name)).join(' · ');
 panel.innerHTML=`<div class="round-result-content"><button type="button" class="round-result-close" data-result-close aria-label="경기 결과 닫고 로비로">닫기 ×</button><header class="round-result-heading"><span>GAME RESULT</span><h2 id="round-result-title">${winners}<em>${data.winners.length>1?'공동 승리':'승리'}</em></h2></header><div class="round-score-table" role="table" aria-label="경기 결과 순위"><div class="round-score-head" role="row"><span role="columnheader">순위</span><span role="columnheader">이름</span><span role="columnheader">남은 패</span><span role="columnheader">점수</span></div>${data.rows.map(row=>`<div class="round-score-row" role="row" data-winner="${row.winner}" data-last="${row.last}"><span class="round-rank" role="cell">${row.shared?'공동 ':''}${row.rank}위</span><span class="round-name" role="cell"><strong>${esc(row.name)}</strong>${row.last?'<small>꼴찌</small>':''}</span><span class="round-left" role="cell">${row.count}장</span><strong class="round-score" role="cell">${row.score>0?'+':''}${row.score}</strong></div>`).join('')}</div>${data.last?`<section class="round-last"><div><span>${data.bet==='none'?'이번 경기 꼴찌':'이번 내기 꼴찌'}</span><strong>${esc(data.last.name)}</strong></div><p>${tieReason[data.decidedBy]||''}</p>${data.draws.length?`<p class="round-draws">${data.draws.map(d=>esc(room.game.players[d.index].name)+' '+d.value).join(' · ')}</p>`:''}${bet.image?`<a class="round-gift" href="${bet.url}" target="_blank" rel="noopener noreferrer"><img src="${new URL('../assets/'+bet.image,import.meta.url).href}" width="32" height="32" alt=""><span>${bet.name}<small>선물하기 ↗</small></span></a>`:''}</section>`:''}${data.shared?'<p class="round-tie-note">공식 점수가 같으면 공동 순위입니다. 내기 꼴찌는 별도 동점 기준으로 정합니다.</p>':''}<p class="round-close-note">우측 상단 닫기를 누르면 대기방 목록으로 돌아갑니다.</p><p class="round-result-error" role="alert">${esc(error)}</p></div>`;
 if(!panel.contains(document.activeElement))panel.querySelector('[data-result-close]')?.focus();
}
